-- schema/ddl/enums/000_enum_tables.sql
--
-- Reference-table DDL for the CDK Twin code lists (pay type, RO status, labour-op
-- type, parts source/price class, GL account type, document type, schedule control
-- key). Hand-authored, not generated by schema/bin/gen_ddl.py, because fields.json
-- (contract EgD-CDK-FIELDS-v2) carries per-field enum_values inline on the field that
-- uses a code, not a standalone code-list catalogue -- these tables ARE that catalogue,
-- built once here so the extract has somewhere to validate against and so tomorrow's
-- discovery has somewhere to land instead of a blank slate.
--
-- Every seed row carries a `confidence` column (DOCUMENTED | INFERRED | UNVERIFIED)
-- and a `source_url` column. Postgres dialect; portable to Snowflake with no dialect-
-- specific syntax (VARCHAR/NUMERIC only, no serial/identity columns).
--
-- Run after schema/ddl/postgres/000_all.sql (these tables are referenced by
-- fk_target-style lookups from the entity tables' *_code columns, though those FKs
-- are not enforced here -- see schema/README.md for why code-list FKs stay soft).

-- ---------------------------------------------------------------------------
-- Shared shape used by every code-list table in this file.
-- code            the literal code as it appears on the CDK screen/payload
-- meaning         plain-language meaning
-- confidence      DOCUMENTED | INFERRED | UNVERIFIED -- per row, never uniform
-- source_url      where this row's meaning was confirmed, or NULL for UNVERIFIED stubs
-- notes           short, only when it earns its place
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS cdk_codelist_pay_type (
    code varchar(4) NOT NULL,
    meaning varchar(128) NOT NULL,
    confidence varchar(11) NOT NULL,
    source_url varchar(512),
    notes varchar(256),
    PRIMARY KEY (code)
);
COMMENT ON TABLE cdk_codelist_pay_type IS 'RO payer settlement rule -- which of three receivable schedules an RO settles to (customer / warranty / internal), per FIELD_CONTRACT.md sap_analogue: internal order (AUFK/COEP) settlement rule.';

INSERT INTO cdk_codelist_pay_type (code, meaning, confidence, source_url, notes) VALUES
    ('C', 'Customer pay', 'DOCUMENTED', 'https://fortellis-api-documents-prod.s3-us-west-2.amazonaws.com/f83a79c6-8cf9-4c1a-b45e-b266634eaf90/external/20251119155158640--ZuFlj8i.pdf', 'Settles to the customer accounting-schedule/receivable.'),
    ('W', 'Warranty pay', 'DOCUMENTED', 'https://fortellis-api-documents-prod.s3-us-west-2.amazonaws.com/f83a79c6-8cf9-4c1a-b45e-b266634eaf90/external/20251119155158640--ZuFlj8i.pdf', 'Settles to the factory/PACCAR warranty receivable schedule.'),
    ('I', 'Internal pay', 'DOCUMENTED', 'https://fortellis-api-documents-prod.s3-us-west-2.amazonaws.com/f83a79c6-8cf9-4c1a-b45e-b266634eaf90/external/20251119155158640--ZuFlj8i.pdf', 'Settles internally -- shop supplies, PDI, or dealer-absorbed cost.'),
    ('U', 'Unconfirmed code', 'UNVERIFIED', NULL, 'Stub row -- confirm remaining pay-type codes (e.g. split/mixed-pay ROs) on tenant login.');

-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS cdk_codelist_ro_status (
