COMMENT ON TABLE cdk_codelist_ro_status IS 'Repair order lifecycle status -- also the accounting-side WIP/closed distinction (work-in-process entity).';

INSERT INTO cdk_codelist_ro_status (code, meaning, confidence, source_url, notes) VALUES
    ('OPEN', 'Open / work in process', 'DOCUMENTED', 'https://fortellis-api-documents-prod.s3-us-west-2.amazonaws.com/f83a79c6-8cf9-4c1a-b45e-b266634eaf90/external/20251119155158640--ZuFlj8i.pdf', 'Carried as WIP on the balance sheet while open.'),
    ('CLOSED', 'Closed / invoiced', 'DOCUMENTED', 'https://fortellis-api-documents-prod.s3-us-west-2.amazonaws.com/f83a79c6-8cf9-4c1a-b45e-b266634eaf90/external/20251119155158640--ZuFlj8i.pdf', 'RO has settled and left WIP.'),
    ('VOID', 'Voided', 'INFERRED', NULL, 'Reasoned from standard DMS RO lifecycle convention; not confirmed field-level in Fortellis docs.'),
    ('UNVERIFIED_STUB', 'Unconfirmed status code', 'UNVERIFIED', NULL, 'Stub row -- CDK likely has intermediate statuses (e.g. dispatched, in-progress by department); confirm on tenant login.');

